EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) select COALESCE(SUM(CASE WHEN COALESCE(capture_stages.detected, 0) = 1 THEN 1 ELSE 0 END), 0) AS detected, COALESCE(SUM(CASE WHEN COALESCE(capture_stages.overlay_shown, 0) = 1 THEN 1 ELSE 0 END), 0) AS overlay_shown, COALESCE(SUM(CASE WHEN COALESCE(capture_stages.share_tapped, 0) = 1 THEN 1 ELSE 0 END), 0) AS share_tapped, COALESCE(SUM(CASE WHEN COALESCE(capture_stages.share_completed, 0) = 1 THEN 1 ELSE 0 END), 0) AS share_completed, COALESCE(SUM(CASE WHEN COALESCE(capture_stages.private_save_tapped, 0) = 1 THEN 1 ELSE 0 END), 0) AS private_save_tapped, COALESCE(SUM(CASE WHEN COALESCE(capture_stages.private_save_completed, 0) = 1 THEN 1 ELSE 0 END), 0) AS private_save_completed, COALESCE(SUM(CASE WHEN COALESCE(capture_stages.share_cancelled, 0) = 1 THEN 1 ELSE 0 END), 0) AS share_cancelled, COALESCE(SUM(CASE WHEN COALESCE(capture_stages.private_save_cancelled, 0) = 1 THEN 1 ELSE 0 END), 0) AS private_save_cancelled, COALESCE(SUM(CASE WHEN COALESCE(capture_stages.share_failed, 0) = 1 THEN 1 ELSE 0 END), 0) AS share_failed, COALESCE(SUM(CASE WHEN COALESCE(capture_stages.private_save_failed, 0) = 1 THEN 1 ELSE 0 END), 0) AS private_save_failed, COALESCE(SUM(CASE WHEN COALESCE(capture_stages.overlay_replaced, 0) = 1 THEN 1 ELSE 0 END), 0) AS overlay_replaced, COALESCE(SUM(CASE WHEN COALESCE(capture_stages.overlay_unavailable, 0) = 1 THEN 1 ELSE 0 END), 0) AS overlay_unavailable, COALESCE(SUM(CASE WHEN COALESCE(capture_stages.overlay_interrupted, 0) = 1 THEN 1 ELSE 0 END), 0) AS overlay_interrupted, COALESCE(SUM(CASE WHEN COALESCE(capture_stages.overlay_shown, 0) = 1 AND (COALESCE(capture_stages.ignored_timeout, 0) = 1 OR COALESCE(capture_stages.ignored_dismissed, 0) = 1) AND NOT COALESCE(capture_stages.share_tapped, 0) = 1 AND NOT COALESCE(capture_stages.private_save_tapped, 0) = 1 THEN 1 ELSE 0 END), 0) AS ignored, COALESCE(SUM(CASE WHEN (COALESCE(capture_stages.share_tapped, 0) = 1 AND (capture_stages.share_latest_terminal IS NULL OR capture_stages.share_latest_start > capture_stages.share_latest_terminal) OR COALESCE(capture_stages.private_save_tapped, 0) = 1 AND (capture_stages.private_save_latest_terminal IS NULL OR capture_stages.private_save_latest_start > capture_stages.private_save_latest_terminal)) THEN 1 ELSE 0 END), 0) AS unfinished, COALESCE(SUM(CASE WHEN COALESCE(capture_stages.share_tapped, 0) = 1 AND COALESCE(capture_stages.share_completed, 0) = 1 THEN 1 ELSE 0 END), 0) AS share_converted, COALESCE(SUM(CASE WHEN COALESCE(capture_stages.private_save_tapped, 0) = 1 AND COALESCE(capture_stages.private_save_completed, 0) = 1 THEN 1 ELSE 0 END), 0) AS private_save_converted from "screenshot_captures" as "c" left join (select "s"."capture_id", MAX(CASE WHEN s.stage = 'detected' THEN 1 ELSE 0 END) AS detected, MAX(CASE WHEN s.stage = 'overlay_shown' THEN 1 ELSE 0 END) AS overlay_shown, MAX(CASE WHEN s.stage = 'share_tapped' THEN 1 ELSE 0 END) AS share_tapped, MAX(CASE WHEN s.stage = 'share_completed' THEN 1 ELSE 0 END) AS share_completed, MAX(CASE WHEN s.stage = 'private_save_tapped' THEN 1 ELSE 0 END) AS private_save_tapped, MAX(CASE WHEN s.stage = 'private_save_completed' THEN 1 ELSE 0 END) AS private_save_completed, MAX(CASE WHEN s.stage = 'share_cancelled' THEN 1 ELSE 0 END) AS share_cancelled, MAX(CASE WHEN s.stage = 'private_save_cancelled' THEN 1 ELSE 0 END) AS private_save_cancelled, MAX(CASE WHEN s.stage = 'share_failed' THEN 1 ELSE 0 END) AS share_failed, MAX(CASE WHEN s.stage = 'private_save_failed' THEN 1 ELSE 0 END) AS private_save_failed, MAX(CASE WHEN s.stage = 'overlay_replaced' THEN 1 ELSE 0 END) AS overlay_replaced, MAX(CASE WHEN s.stage = 'overlay_unavailable' THEN 1 ELSE 0 END) AS overlay_unavailable, MAX(CASE WHEN s.stage = 'overlay_interrupted' THEN 1 ELSE 0 END) AS overlay_interrupted, MAX(CASE WHEN s.stage = 'ignored_timeout' THEN 1 ELSE 0 END) AS ignored_timeout, MAX(CASE WHEN s.stage = 'ignored_dismissed' THEN 1 ELSE 0 END) AS ignored_dismissed, MAX(CASE WHEN s.stage IN ('share_tapped', 'share_started') THEN COALESCE(s.last_occurred_at, s.occurred_at) END) AS share_latest_start, MAX(CASE WHEN s.stage IN ('share_completed', 'share_cancelled', 'share_failed') THEN COALESCE(s.last_occurred_at, s.occurred_at) END) AS share_latest_terminal, MAX(CASE WHEN s.stage IN ('private_save_tapped', 'private_save_started') THEN COALESCE(s.last_occurred_at, s.occurred_at) END) AS private_save_latest_start, MAX(CASE WHEN s.stage IN ('private_save_completed', 'private_save_cancelled', 'private_save_failed') THEN COALESCE(s.last_occurred_at, s.occurred_at) END) AS private_save_latest_terminal from "screenshot_capture_stages" as "s" where "s"."capture_id" in (select "c"."id" from "screenshot_captures" as "c") group by "s"."capture_id") as "capture_stages" on "capture_stages"."capture_id" = "c"."id";
